<?php
require_once __DIR__.'/../includes/bootstrap.php';
try {
    $db=fleet_db();$q=trim((string)($_GET['q']??''));$location=trim((string)($_GET['location']??''));$type=(string)($_GET['type']??'');$page=max(1,(int)($_GET['page']??1));$limit=30;$export=(string)($_GET['export']??'')==='1';
    $sql="SELECT a.id,a.primary_identifier,a.registration_status,t.type_name,t.type_code,ai.source_note FROM assets a JOIN asset_types t ON t.id=a.asset_type_id LEFT JOIN asset_identifiers ai ON ai.asset_id=a.id AND ai.is_primary=1 WHERE a.is_active=1 AND a.registration_status='UNREGISTERED' ORDER BY a.primary_identifier";
    $records=$db->query($sql)->fetchAll();$sources=[];foreach($db->query('SELECT id,source_code FROM spreadsheet_sources') as $r)$sources[$r['source_code']]=(int)$r['id'];$sheets=[];foreach($db->query('SELECT id,source_id,sheet_name FROM spreadsheet_sheets') as $r)$sheets[$r['sheet_name'].'|'.$r['source_id']]=(int)$r['id'];$rowStmt=$db->prepare('SELECT raw_data FROM spreadsheet_source_row_versions WHERE sync_run_id=? AND sheet_id=? AND source_row_number=? LIMIT 1');$items=[];$allLocations=[];
    $typeCodes=['HORSE'=>'TRUCK_HEAD','TANKER'=>'TANKER_TRAILER','FLATBED'=>'FLATBED_TRAILER'];
    foreach($records as $r){$loc='Unspecified';$note=(string)($r['source_note']??'');if(preg_match('/^([^\/]+)\/([^\/]+) row (\d+) col ([A-Z]+)/',$note,$m)){$code=$m[1];$sheet=$m[2];$row=(int)$m[3];if(str_starts_with($sheet,'Ngwerere_')||$sheet==='Unregistered_Ngwerere')$loc='Ngwerere';elseif($sheet==='Registered_21Miles')$loc='21 Miles';elseif(str_starts_with($sheet,'Nakonde_')){$sid=$sheets[$sheet.'|'.($sources[$code]??0)]??0;preg_match('/\(run (\d+)\)/',$note,$rm);$run=(int)($rm[1]??0);$rowStmt->execute([$run,$sid,$row]);$raw=$rowStmt->fetchColumn();$cells=$raw===false?[]:(json_decode((string)$raw,true)?:[]);$yard=trim((string)($cells[$sheet==='Nakonde_Tankers_unregistered'?3:4]??''));$loc=$yard!==''&&!preg_match('/^(total|nakonde_flatbeds)/i',$yard)?$yard:'Nakonde';}}
        $allLocations[$loc]=($allLocations[$loc]??0)+1;$r['source_location']=$loc;$hay=strtolower(implode(' ',[$r['primary_identifier'],$r['type_name'],$note,$loc]));if($q!==''&&!str_contains($hay,strtolower($q)))continue;if(isset($typeCodes[$type])&&$r['type_code']!==$typeCodes[$type])continue;if($location!==''&&$loc!==$location)continue;unset($r['source_note']);$items[]=$r;}
    arsort($allLocations);$total=count($items);$pageItems=$export?$items:array_slice($items,($page-1)*$limit,$limit);json_response(['ok'=>true,'items'=>$pageItems,'total'=>$total,'pages'=>(int)ceil($total/$limit),'page'=>$page,'locations'=>$allLocations]);
}catch(Throwable $e){error_log('Unregistered assets report: '.$e->getMessage());json_response(['ok'=>false,'message'=>'Unregistered assets could not be loaded.'],500);}
